    "logo",
    "favicon",
    "avatar",
    "icon",
    "advertisement",
    "ad_",
    "_ad",
    "/ads/",
    "banner",
    "pixel",
    "1x1",
    "tracking",
    "analytics",
    "share",
    "social",
    "button",
    "badge",
    "sponsor",
    "placeholder",
    "default_thumb",
    "spinner",
    "loader",
    "loading",
    "widget",
    "counter",
    "wp-content/themes",
    "/themes/",
    "/static/images/logo"
